package lk.ac.sliit.ridelink.ride.infrastructure.security;
import com.fasterxml.jackson.databind.ObjectMapper; import jakarta.servlet.http.*; import org.springframework.http.*; import org.springframework.security.access.AccessDeniedException; import org.springframework.security.web.access.AccessDeniedHandler; import org.springframework.stereotype.Component; import java.io.IOException; import java.time.Instant; import java.util.*;
@Component public class RestAccessDeniedHandler implements AccessDeniedHandler {private final ObjectMapper mapper;public RestAccessDeniedHandler(ObjectMapper mapper){this.mapper=mapper;}public void handle(HttpServletRequest req,HttpServletResponse res,AccessDeniedException e)throws IOException{res.setStatus(403);res.setContentType(MediaType.APPLICATION_JSON_VALUE);mapper.writeValue(res.getOutputStream(),Map.of("timestamp",Instant.now(),"status",403,"error","Forbidden","message","You do not have permission to perform this operation","path",req.getRequestURI(),"validationErrors",List.of()));}}
